\documentclass[11pt]{article}

\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\newtheorem{theorem}{Theorem}[section]
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\DeclareMathOperator{\ConflictFree}{ConflictFree}
\DeclareMathOperator{\Defends}{Defends}
\DeclareMathOperator{\Admissible}{Admissible}
\DeclareMathOperator{\Complete}{Complete}
\DeclareMathOperator{\Preferred}{Preferred}
\DeclareMathOperator{\Stable}{Stable}
\DeclareMathOperator{\MaximalConflictFree}{MaximalConflictFree}
\newcommand{\GE}{\mathrm{GE}}
\newcommand{\lfp}{\operatorname{lfp}}
\newcommand{\AF}{\mathrm{AF}}

\title{Stable Extensions in Abstract Argumentation:\\
The Semantic Hierarchy, the Symmetric Collapse,\\
and an Euler Correspondence}
\author{Aristotle}
\date{2026-07-12}

\begin{document}
\maketitle

\begin{abstract}
We develop, from first principles, the theory of \emph{stable extensions} in
Dung's abstract argumentation frameworks and locate them precisely within the
classical lattice of extension-based semantics. We prove that every stable
extension is simultaneously preferred, complete, admissible, and conflict-free,
forming the implication chain
\[
\text{stable} \implies \text{preferred} \implies \text{complete}
\implies \text{admissible} \implies \text{conflict-free},
\]
and that every stable extension is a \emph{facet} --- a maximal conflict-free set
--- of the \emph{coexistence complex} $K(\AF)$. We show that the grounded
(skeptical) extension is contained in every stable extension. For
\textbf{symmetric, irreflexive} frameworks we establish an exact collapse of the
top of the hierarchy: a set is stable if and only if it is preferred if and only
if it is a facet of $K(\AF)$. Finally, specialising to the complete conflict
graph on $n$ arguments, we prove that its stable extensions are exactly the $n$
singletons and that the Euler characteristic of $K(\AF)$ equals the number of
stable extensions, giving a clean bridge between a combinatorial--logical count
and a topological invariant.
\end{abstract}

\section{Introduction}

An \emph{abstract argumentation framework} in the sense of Dung is a pair
$(\mathrm{Ar}, R)$ consisting of a set $\mathrm{Ar}$ of arguments and a binary
\emph{attack} relation $R$; we read $R\,a\,b$ as ``$a$ attacks $b$''. Essentially
the whole theory of rational acceptance can be phrased in terms of these two
ingredients, by singling out the sets of arguments that may reasonably be
accepted together. Such sets are called \emph{extensions}, and different standards
of reasonableness give rise to different \emph{semantics}.

This paper concentrates on the strongest of the classical extension-based
semantics, the \textbf{stable extension}, and develops three interlocking themes:
(1) its placement at the top of the semantic hierarchy; (2) the exact
\emph{symmetric collapse} of the top of that hierarchy for symmetric irreflexive
frameworks; and (3) an \emph{Euler correspondence} for the complete conflict graph
linking a logical count to a topological invariant.

Throughout we work with an arbitrary type $A$ of arguments and an arbitrary
relation $R : A \to A \to \mathrm{Prop}$, specialising to finite frameworks only
where cardinalities and Euler characteristics are computed.

\section{Definitions}

Fix a framework $(A, R)$ and consider sets $S \subseteq A$.

\begin{definition}[Conflict-free]
$S$ is \emph{conflict-free} if
$\ConflictFree(S) \iff \forall a \in S,\ \forall b \in S,\ \neg\, R\,a\,b$.
\end{definition}

\begin{definition}[Defense]
$S$ \emph{defends} $a$ if
$\Defends(S, a) \iff \forall b,\ R\,b\,a \implies \exists c \in S,\ R\,c\,b$.
\end{definition}

\begin{definition}[Admissible]
$S$ is \emph{admissible} if
$\Admissible(S) \iff \ConflictFree(S) \wedge \forall a \in S,\ \Defends(S, a)$.
\end{definition}

\begin{definition}[Characteristic operator]
The \emph{characteristic (defense) operator} is
$F(S) = \{\, a \mid \Defends(S, a) \,\}$.
\end{definition}

\begin{definition}[Complete]
$S$ is \emph{complete} if
$\Complete(S) \iff \Admissible(S) \wedge F(S) \subseteq S$.
\end{definition}

\begin{definition}[Preferred]
$S$ is \emph{preferred} if it is a maximal admissible set:
$\Preferred(S) \iff \Admissible(S) \wedge \big(\forall T,\ \Admissible(T)
\wedge S \subseteq T \implies T = S\big)$.
\end{definition}

\begin{definition}[Maximal conflict-free / facet]
$S$ is \emph{maximal conflict-free} if
$\MaximalConflictFree(S) \iff \ConflictFree(S) \wedge \big(\forall T,\
\ConflictFree(T) \wedge S \subseteq T \implies T = S\big)$.
\end{definition}

\begin{definition}[Stable]
$S$ is a \emph{stable extension} if it is conflict-free and attacks every
argument it does not contain:
\[
\Stable(S) \iff \ConflictFree(S) \wedge \big(\forall a \notin S,\
\exists b \in S,\ R\,b\,a\big).
\]
\end{definition}

\begin{definition}[Coexistence complex $K(\AF)$]
The \emph{coexistence complex} has as its faces exactly the finite conflict-free
sets of arguments. Since conflict-freeness is inherited by subsets, this is a
genuine abstract simplicial complex; its facets are precisely the maximal
conflict-free sets.
\end{definition}

\begin{lemma}[Monotonicity of defense]\label{lem:mono}
If $S \subseteq T$ and $S$ defends $a$, then $T$ defends $a$. Consequently $F$ is
monotone.
\end{lemma}
\begin{proof}
A counter-attacker $c \in S$ of an attacker of $a$ also lies in $T \supseteq S$.
\end{proof}

\section{The Stable Hierarchy}

\begin{lemma}[Stable sets are self-defending]\label{lem:stabledef}
If $S$ is stable and $a \in S$, then $S$ defends $a$.
\end{lemma}
\begin{proof}
Let $b$ attack $a$. If $b \in S$ then $S$ contains the conflict $b\!\to\!a$,
contradicting conflict-freeness; so $b \notin S$, and stability yields $c \in S$
attacking $b$, a defense of $a$.
\end{proof}

\begin{theorem}[Stable $\implies$ admissible]
Every stable extension is admissible.
\end{theorem}
\begin{proof}
Immediate from conflict-freeness and Lemma~\ref{lem:stabledef}.
\end{proof}

\begin{theorem}[Stable $\implies$ complete]
Every stable extension is complete.
\end{theorem}
\begin{proof}
It is admissible, so we show $F(S) \subseteq S$. If $a \in F(S)$ but $a \notin S$,
stability gives $b \in S$ attacking $a$; as $S$ defends $a$, some $c \in S$
attacks $b$, so $b, c \in S$ with $c$ attacking $b$ contradicts
conflict-freeness. Hence $a \in S$.
\end{proof}

\begin{theorem}[Stable $\implies$ preferred]
Every stable extension is preferred.
\end{theorem}
\begin{proof}
$S$ is admissible. Let $T$ be admissible with $S \subseteq T$ and take $a \in T$.
If $a \notin S$, stability gives $b \in S \subseteq T$ attacking $a$, so $T$
contains a conflict, contradiction. Hence $a \in S$ and $T = S$.
\end{proof}

\begin{theorem}[Stable sets are facets]
Every stable extension is maximal conflict-free.
\end{theorem}
\begin{proof}
$S$ is conflict-free. If $T \supseteq S$ is conflict-free and $a \in T$ with
$a \notin S$, stability gives $b \in S \subseteq T$ attacking $a$, contradicting
conflict-freeness of $T$. Hence $T = S$.
\end{proof}

These realise the chain
$\text{stable} \implies \text{preferred} \implies \text{complete}
\implies \text{admissible} \implies \text{conflict-free}$, with stable
extensions being exactly facets of $K(\AF)$.

\section{The Grounded Extension Lies Below Every Stable Extension}

Because $F$ is monotone on the complete lattice of subsets of $A$
(Lemma~\ref{lem:mono}), Knaster--Tarski provides a least fixed point.

\begin{definition}[Grounded extension]
$\GE = \lfp(F)$, the least fixed point of the monotone operator $F$.
\end{definition}

\begin{lemma}[Least prefixed point]\label{lem:lfp}
If $F(S) \subseteq S$ then $\GE \subseteq S$.
\end{lemma}

\begin{theorem}[Grounded $\subseteq$ every stable]
The grounded extension is contained in every stable extension.
\end{theorem}
\begin{proof}
A stable $S$ is complete, so $F(S) \subseteq S$; Lemma~\ref{lem:lfp} gives
$\GE \subseteq S$.
\end{proof}

\section{The Symmetric Collapse}

We specialise to \emph{symmetric} frameworks ($R\,a\,b \implies R\,b\,a$) that are
\emph{irreflexive} ($\neg R\,a\,a$).

\begin{lemma}[Free self-defense]
In a symmetric framework, if $a \in S$ then $S$ defends $a$.
\end{lemma}
\begin{proof}
If $b$ attacks $a$, symmetry gives that $a$ attacks $b$, and $a \in S$.
\end{proof}

\begin{corollary}\label{cor:cfadm}
In a symmetric framework every conflict-free set is admissible.
\end{corollary}

\begin{proposition}[Preferred $=$ facet]\label{prop:preffacet}
In a symmetric framework, $S$ is preferred iff it is maximal conflict-free.
\end{proposition}
\begin{proof}
By Corollary~\ref{cor:cfadm} the admissible sets are exactly the conflict-free
sets, so maximality among the one class coincides with maximality among the other.
\end{proof}

\begin{proposition}[Facets are stable]\label{prop:facetstable}
In a symmetric irreflexive framework, every maximal conflict-free set is stable.
\end{proposition}
\begin{proof}
Let $S$ be maximal conflict-free and suppose some $a \notin S$ is attacked by no
member of $S$. Then $S \cup \{a\}$ is conflict-free: a conflict within it cannot
be $R\,a\,a$ (irreflexivity), cannot be between $a$ and $y \in S$ (that would give
$R\,y\,a$ by symmetry, against our assumption), and cannot be within $S$. This
contradicts maximality. Hence every $a \notin S$ is attacked from $S$, i.e. $S$ is
stable.
\end{proof}

\begin{theorem}[The symmetric collapse]
In a symmetric irreflexive framework,
\[
\Stable(S) \iff \Preferred(S) \iff \MaximalConflictFree(S).
\]
\end{theorem}
\begin{proof}
Stable $\Rightarrow$ facet (Section 3); facet $\Rightarrow$ stable
(Proposition~\ref{prop:facetstable}); facet $\iff$ preferred
(Proposition~\ref{prop:preffacet}).
\end{proof}

\section{The Complete Conflict Graph and the Euler Bridge}

\begin{definition}[Complete conflict graph]
The \emph{complete conflict graph} on $n$ arguments is $(\{1,\dots,n\}, R)$ with
$R\,a\,b \iff a \neq b$.
\end{definition}

\begin{lemma}
The complete conflict graph is symmetric and irreflexive.
\end{lemma}

\begin{lemma}[Conflict-free $=$ subsingleton]\label{lem:sub}
In the complete conflict graph, $S$ is conflict-free iff $|S| \le 1$.
\end{lemma}
\begin{proof}
$\neg R\,a\,b$ means $a = b$; so a conflict-free set has no two distinct elements,
and conversely.
\end{proof}

\begin{theorem}[Stable $=$ singleton]
For $n \ge 1$, the stable extensions of the complete conflict graph are exactly
the singletons.
\end{theorem}
\begin{proof}
By the symmetric collapse, stable coincides with maximal conflict-free; by
Lemma~\ref{lem:sub} the conflict-free sets are subsingletons, whose maximal
members (with $n \ge 1$) are exactly the singletons. Directly: $\{a\}$ is
conflict-free and attacks every $b \ne a$; a stable set is a nonempty
subsingleton, hence a singleton.
\end{proof}

\begin{theorem}[Count of stable extensions]\label{thm:count}
For $n \ge 1$, the complete conflict graph has exactly $n$ stable extensions.
\end{theorem}
\begin{proof}
The map $a \mapsto \{a\}$ is a bijection from the $n$ arguments onto the stable
extensions.
\end{proof}

\subsection{Euler characteristic}

For a finite framework, with $\mathcal{F}$ the family of conflict-free faces,
\[
\chi = \sum_{\substack{s \in \mathcal{F} \\ s \neq \varnothing}} (-1)^{\,|s|-1}
= f_0 - f_1 + f_2 - \cdots,
\]
where $f_k$ counts the $k$-dimensional faces (those with $k+1$ elements).

\begin{lemma}[Faces of the complete conflict graph]
The faces of the complete conflict graph on $n$ arguments are exactly the finite
sets of cardinality at most one.
\end{lemma}

\begin{theorem}[Euler characteristic]\label{thm:euler}
The Euler characteristic of the coexistence complex of the complete conflict graph
on $n$ arguments is $n$.
\end{theorem}
\begin{proof}
The complex is $n$ isolated points; only the $n$ singletons contribute, each with
sign $+1$.
\end{proof}

\begin{theorem}[The stable Euler bridge]
For the complete conflict graph on $n \ge 1$ arguments,
\[
\chi\big(K(\AF)\big) = \#\{\text{stable extensions}\} = n.
\]
\end{theorem}
\begin{proof}
Combine Theorem~\ref{thm:euler} with Theorem~\ref{thm:count}.
\end{proof}

For example, at $n = 4$ both sides equal $4$.

\section{Algorithms}

\textbf{Stability test.} Verify conflict-freeness (no attack within $S$) and
domination (every outside argument has an attacker in $S$); quadratic per
candidate.

\textbf{Enumerate stable extensions.} Test all subsets; exponential in general,
but for symmetric irreflexive frameworks reduces to enumerating maximal
independent sets of the conflict graph.

\textbf{Grounded extension.} Iterate $F$ from $\varnothing$ to its least fixed
point.

\textbf{Euler characteristic.} Sum $(-1)^{|s|-1}$ over nonempty conflict-free
sets; for the complete conflict graph this is a count of singletons.

\section{Applications and Future Work}

Abstract argumentation underlies reasoning with inconsistent information: legal
argumentation, negotiation, decision support, and inconsistency-tolerant querying.
The stable hierarchy certifies weaker standards for free; grounded containment
provides a shared skeptical core; the symmetric collapse reduces stable
computation to maximal independent sets; and the Euler bridge recasts a counting
problem topologically.

Future directions include extending the symmetric collapse and Euler bridge to
arbitrary symmetric irreflexive frameworks via the independence complex,
characterising the frameworks that admit at least one stable extension, and
replacing the Euler characteristic by the reduced homology of the coexistence
complex.

\section{Conclusion}

Stable extensions sit at the apex of the extension-based hierarchy, contain the
grounded skeptical core, coincide with preferred extensions and facets in the
symmetric irreflexive setting, and --- for the complete conflict graph --- are
counted exactly by the Euler characteristic of the coexistence complex.

\end{document}

