               for s in powerset(args) if s and conflict_free(R, s))

def complete_graph(n: int) -> Tuple[List[int], Attack]:
    return list(range(n)), (lambda a, b: a != b)

if __name__ == "__main__":
    print(f"{'n':>3} {'#stable':>8} {'chi':>5}")
    for n in range(1, 9):
        args, R = complete_graph(n)
        ns = sum(1 for S in powerset(args) if stable(args, R, S))
        chi = euler(args, R)
        print(f"{n:>3} {ns:>8} {chi:>5}")
        assert ns == chi == n
    print("Euler bridge verified")

"""Compute the grounded (skeptical) extension as the least fixed point of the
defense operator and confirm it lies inside every stable extension."""
from __future__ import annotations
from itertools import combinations
from typing import Callable, FrozenSet, List, Set, Tuple

Attack = Callable[[int, int], bool]
Ext = FrozenSet[int]

def powerset(args: List[int]) -> List[Ext]:
    return [frozenset(c) for r in range(len(args)+1) for c in combinations(args, r)]

def conflict_free(R: Attack, S: Ext) -> bool:
    return not any(R(a, b) for a in S for b in S)

def defends_in(args: List[int], R: Attack, S: Ext, a: int) -> bool:
    return all(any(R(c, b) for c in S) for b in args if R(b, a))

def char_F(args: List[int], R: Attack, S: Ext) -> Ext:
    return frozenset(a for a in args if defends_in(args, R, S, a))

def grounded(args: List[int], R: Attack) -> Ext:
    S: Ext = frozenset()
    while True:
        nxt = char_F(args, R, S)
        if nxt == S:
            return S
        S = nxt

def stable(args: List[int], R: Attack, S: Ext) -> bool:
    return conflict_free(R, S) and all(
        any(R(b, a) for b in S) for a in args if a not in S)

def framework(n: int, edges: Set[Tuple[int, int]]) -> Tuple[List[int], Attack]:
    e = set(edges)
    return list(range(n)), (lambda a, b: (a, b) in e)

if __name__ == "__main__":
    # a reinstatement chain: 0 unattacked defends 2 against 1
    args, R = framework(3, {(0, 1), (1, 2)})
    G = grounded(args, R)
    print("grounded =", sorted(G))
    for S in powerset(args):
        if stable(args, R, S):
            print("stable", sorted(S), "contains grounded:", G <= S)
            assert G <= S
    print("grounded-below-stable verified")

