from itertools import combinations
from typing import Callable, FrozenSet, List

Attack = Callable[[int, int], bool]

def is_stable(args: List[int], R: Attack, S: FrozenSet[int]) -> bool:
    if any(R(a, b) for a in S for b in S):
        return False
