def enumerate_stable(args: List[int], R: Attack) -> List[FrozenSet[int]]:
    """Return all stable extensions by testing every subset.

    Worst-case O(2^n * n^2); deciding existence of a stable extension is
    NP-complete for general frameworks, so exhaustive search is appropriate
    only for small n or as a reference oracle.
    """
    result: List[FrozenSet[int]] = []
    for r in range(len(args) + 1):
        for combo in combinations(args, r):
            S = frozenset(combo)
            if is_stable(args, R, S):
                result.append(S)
    return result

